{
  "items": [
    {
      "name": "Finset.card_pi",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : ι → Type u_6} [inst : DecidableEq ι] (s : Finset ι) (t : (i : ι) → Finset (α i)),\n  (s.pi t).card = ∏ i ∈ s, (t i).card"
    },
    {
      "name": "Nat.card_fun",
      "module_name": "Mathlib.SetTheory.Cardinal.Finite",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [Finite α], Nat.card (α → β) = Nat.card β ^ Nat.card α"
    },
    {
      "name": "Fintype.card_filter_piFinset_eq_of_mem",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : ι → Type u_6} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  (s : (i : ι) → Finset (α i)) (i : ι) {a : α i},\n  a ∈ s i → {f ∈ Fintype.piFinset s | f i = a}.card = ∏ j ∈ Finset.univ.erase i, (s j).card"
    },
    {
      "name": "Fintype.card_pi_const",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ (α : Type u_7) [inst : Fintype α] (n : ℕ), Fintype.card (Fin n → α) = Fintype.card α ^ n"
    },
    {
      "name": "Fintype.card_filter_piFinset_const_eq_of_mem",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {κ : Type u_5} [inst : DecidableEq ι] [inst_1 : DecidableEq κ] [inst_2 : Fintype ι] (s : Finset κ)\n  (i : ι) {x : κ}, x ∈ s → {f ∈ Fintype.piFinset fun x => s | f i = x}.card = s.card ^ (Fintype.card ι - 1)"
    }
  ]
}
